require_once 'inc/db.php';require_once 'inc/auth.php';if((int)$_SESSION['role_id']!==1){http_response_code(403);die('Access denied.');}$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$db->prepare('UPDATE tbl_system_settings SET system_name=?,organization=?,contact_email=?,contact_phone=?,address=? WHERE id=?')->execute([trim($_POST['system_name']),trim($_POST['organization']),trim($_POST['contact_email']),trim($_POST['contact_phone']),trim($_POST['address']),$settings['id']]);audit_log($db,'SYSTEM_SETTINGS_UPDATED','Organization configuration updated');$msg='System settings saved.';$settings=$db->query('SELECT * FROM tbl_system_settings LIMIT 1')->fetch(PDO::FETCH_ASSOC);}$page_title='System Settings';$breadcrumb='Administration';include 'inc/links.php';include 'inc/header.php';?>
